/* ===== State ===== */
const NEWDEAL=()=>({id:'d'+Date.now().toString(36)+Math.floor(Math.random()*999),p:{county:'Cook',sale:'judicial'},k:{},v:{arvC:0,arvE:0,arvO:0,rep:0,repP:10,legal:3500,poss:5000,carry:900,mo:6,sell:8,profP:15,profD:0,cont:3,prem:0,tt:0.15,cap:8,dep:10}});
let DB=JSON.parse(localStorage.getItem('desk2')||'null');
if(!DB){const o=JSON.parse(localStorage.getItem('desk')||'null'),d=o?Object.assign(NEWDEAL(),o):NEWDEAL();DB={cur:d.id,deals:{[d.id]:d}}}
let S=DB.deals[DB.cur];
function ensure(){S.t=Object.assign({county:'Cook',date:'2026-12-15',cls:'res',amt:0,rate:12,subs:0,deedc:12000,fee:0,val:0,tgt:15,hold:12,redm:''},S.t||{});S.a=Object.assign({visits:[],contacts:[],who:{},sit:'own',me:'',ph:'',lt:'owner'},S.a||{});S.v.unseen=S.v.unseen??30;S.v.sqft=S.v.sqft||0;S.g=S.g||{};S.c=S.c||[]}
ensure();
let cur=Object.keys(DB.deals).length>1?0:1;const $=id=>document.getElementById(id),m=n=>(n<0?'-$':'$')+Math.abs(Math.round(n)).toLocaleString();
const save=()=>{S.u=Date.now();DB.deals[DB.cur]=S;DB.cur=S.id;localStorage.setItem('desk2',JSON.stringify(DB));side()};

/* ===== Calculator (cash buyer: no loan, but cash has a cost) ===== */
const repC=()=>S.p.acc==='full'?S.v.repP:Math.max(S.v.repP,S.v.unseen);
function bid(arv){const v=S.v,cm=v.cap/100*v.mo/12,rep=v.rep*(1+repC()/100);
 const fixed=rep+v.legal+v.poss+v.carry*v.mo+exposure()+arv*(v.sell+v.cont)/100+Math.max(v.profD,arv*v.profP/100)+cm*v.rep;
 return Math.max(0,(arv-fixed)/(1+v.prem/100+v.tt/100+cm));}
const cashNeeded=b=>{const v=S.v;return b*(1+v.prem/100+v.tt/100)+v.rep*(1+repC()/100)+v.legal+v.poss+exposure()};
const exposure=()=>Object.values(S.k).reduce((a,x)=>a+((x.s==='issue'||x.s==='kill')?+x.a||0:0),0);
const all=()=>STAGES.flatMap(s=>s.c||[]);const key=(s,i)=>s.id+i;
function status(){let open=0,kill=[];STAGES.forEach(s=>(s.c||[]).forEach((c,i)=>{if(off(c))return;const x=S.k[key(s,i)]||{};if(!x.s||x.s==='un')open++;if(x.s==='kill')kill.push(c.t)}));return{open,kill}}
const GATES=[['bk','Bankruptcy: searched PACER the morning of the sale (owner and co-borrowers). An active filing means no bid.'],['ttl','Title: search ordered and read; surviving liens, taxes and association dues entered as exposure.'],['dkt','Docket and notice: confirmed within 24 hours that the sale is not stayed, postponed or vacated, and read the Notice of Sale.'],['wire','Money: certified funds ready; any wire instructions verified by phone at a number you found yourself.'],['asis','Risk: I accept as-is, usually no interior inspection, and that my deposit is at risk if I fail to close.'],['fund','Funds: verified cash covers the total cash to deploy.'],['ent','Who bids and who takes title is decided.']];
const gOk=k=>S.g[k]||(k==='fund'&&S.funds&&S.funds>=cashNeeded(bid(S.v.arvC)));
const gatesOpen=()=>GATES.filter(g=>!gOk(g[0])).length;
function gateUI(){const n=gatesOpen(),auto=S.funds&&S.funds>=cashNeeded(bid(S.v.arvC));return`<div class="gate ${n?'':'ok'}"><b>Pre-bid gates: ${n?n+' open. Do not bid until all are checked.':'all clear'}</b>${GATES.map(g=>`<label><input type="checkbox" ${gOk(g[0])?'checked':''} ${g[0]==='fund'&&auto?'disabled':''} onchange="setg('${g[0]}',this.checked)">${g[1]}</label>`).join('')}</div>`}
window.setg=(k,v)=>{S.g[k]=v;save();const e=document.querySelector('.gate');if(e)e.outerHTML=gateUI()};
function side(){const b=bid(S.v.arvC),{open,kill}=status(),v=S.v;
 $('ceil').textContent=S.v.arvC?m(b):'—';
 const cl=(c,t)=>`<span style="color:var(--${c})">${t}</span>`,go_=gatesOpen();
 $('verd').innerHTML=kill.length?cl('bad','WALK AWAY – dealbreaker flagged'):!v.arvC?'Enter comps to price':(+S.p.cb&&b<+S.p.cb)?cl('bad',`Ceiling is below the ${m(+S.p.cb)} opening/credit bid. You likely cannot win at a price that works.`):go_?cl('warn',`DO NOT BID YET – ${go_} pre-bid gates open`):open?cl('warn',`Provisional – ${open} checks open`):cl('ok','Cleared to bid up to the ceiling');
 const bn=$('bn');if(bn)bn.innerHTML=sb?'':'<div class="banner">Not signed in. <a href="/investor/">Sign in</a></div>';
 const cash=cashNeeded(b);
 $('side').innerHTML=[['Surviving liens/exposure',m(exposure())],['Deposit at sale ('+v.dep+'%)',m(b*(1+v.prem/100)*v.dep/100)],['Total cash to deploy',m(cash)],['Verified funds',S.funds?m(S.funds)+(S.funds>=cash?' ✓':' ✗ short'):'not verified']].map(r=>`<div class="row"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}

/* ===== Render ===== */
function nav(){$('nav').innerHTML='<h1>Cash Acquisition Desk</h1><div class="lead" style="font-size:13px;margin-bottom:10px">'+esc(S.p.addr||S.p.pin||'Untitled deal')+'</div>'+STAGES.map((s,i)=>{const d=(s.c||[]).filter((c,j)=>{const x=S.k[key(s,j)];return !off(c)&&x&&x.s&&x.s!=='un'}).length;return`<button class="${i==cur?'on':''}" onclick="go(${i})">${s.n}<small>${s.c?d+'/'+s.c.filter(c=>!off(c)).length:''}</small></button>`}).join('')+'<div id="who" class="lead" style="margin-top:14px;font-size:13px"></div>'}
window.go=i=>{cur=i;draw()};
const sel=(k,l,o)=>`<label>${l}<select onchange="setv('${k}',this.value,'p')">${o.map(x=>`<option${S.p[k]==x?' selected':''}>${x}</option>`).join('')}</select></label>`;
const inp=(k,l,o={})=>`<label>${l}<input type="${o.t||'number'}" step="any" value="${(o.o||S.v)[k]??''}" onchange="setv('${k}',this.value,${o.o?"'"+(o.w||'p')+"'":"'v'"})"></label>`;
window.setv=(k,x,w)=>{S[w][k]=(w==='p'||w==='t'&&['county','date','cls'].includes(k)||isNaN(x)||x==='')?x:+x;save();if(w==='t')lienOut()};
window.setk=(id,f,x)=>{(S.k[id]=S.k[id]||{})[f]=x;save();nav();side()};
window.open2=(u,t)=>{const p=S.p,v={addr:p.addr,pin:p.pin,name:p.owner}[t]||'';if(v)try{navigator.clipboard.writeText(v).catch(()=>{})}catch(e){}window.open(u+(t==='addr'&&u.includes('query=')?encodeURIComponent(v||''):''),'_blank','noopener')};
// One big county label so there is no chance of researching in the wrong county. Changing it is deliberate (a button).
let cLock=true;
window.unlockCounty=()=>{cLock=false;draw()};
window.lockCounty=()=>{cLock=true;draw()};
function countyBox(){const c=S.p.county||'Cook';if(!cLock)return sel('county','County',['Cook','Lake','McHenry','Boone','Winnebago','Kane','Other'])+`<p class="noprint"><button class="btn o" onclick="lockCounty()">Done</button></p>`;
 return `<div style="grid-column:1/-1;background:#12304f;color:#fff;border-radius:8px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><div><div style="font-size:12px;opacity:.8;letter-spacing:.06em">THIS PROPERTY IS IN</div><div style="font-size:26px;font-weight:700">${c==='Other'?'COUNTY NOT SET':esc(c.toUpperCase())+' COUNTY, IL'}</div><div style="font-size:13px;opacity:.85">Only ${c==='Other'?'general':esc(c)+' County'} sources are shown below.</div></div><button class="btn o noprint" style="background:#fff" onclick="unlockCounty()">Wrong county? Change</button></div>`}
function draw(){nav();const s=STAGES[cur];let h=`<section><h2>${s.n}</h2><p class="lead">${s.d}</p>`;
 if(s.id==='id')h+=`<div class="g">${inp('addr','Property address',{t:'text',o:S.p})}${inp('pin','PIN / Parcel ID',{t:'text',o:S.p})}${inp('owner','Owner name (on deed)',{t:'text',o:S.p})}
 ${countyBox()}
 <label>Sale type<select onchange="setv('sale',this.value,'p')">${Object.entries(SALES).map(([k,x])=>`<option value="${k}"${S.p.sale==k?' selected':''}>${x.n}</option>`).join('')}</select></label>
 ${inp('date','Sale date',{t:'date',o:S.p})}${inp('case','Case number',{t:'text',o:S.p})}${inp('plf','Plaintiff / attorney',{t:'text',o:S.p})}${inp('plph','Attorney phone',{t:'text',o:S.p})}${inp('venue','Sale conducted by / venue',{t:'text',o:S.p})}${inp('cb','Opening / credit bid $',{o:S.p})}${inp('pay','Payment terms (from notice)',{t:'text',o:S.p})}${sel('occ','Occupancy',['Unknown','Occupied','Vacant'])}${sel('insp','Interior inspection',['Unknown','Not permitted','Allowed'])}</div><p class="cfg">Clicking any link below copies the PIN, address or owner name to your clipboard, then opens the source. Paste it into the site’s search box.</p>`;
 (s.c||[]).forEach((c,i)=>{if(off(c))return;const id=key(s,i),x=S.k[id]||{};h+=`<div class="chk"><div><a href="#" onclick="open2('${c.u}','${c.cp}');return false">${c.t}</a><div class="w">${c.w}${c.k?` <span class="red">Dealbreaker if: ${c.k}</span>`:''}</div></div>
 <select onchange="setk('${id}','s',this.value)">${[['un','Unchecked'],['ok','Clear'],['issue','Issue (costs $)'],['kill','Dealbreaker']].map(o=>`<option value="${o[0]}"${x.s==o[0]?' selected':''}>${o[1]}</option>`).join('')}</select>
 <input type="number" placeholder="$ exposure" value="${x.a||''}" onchange="setk('${id}','a',this.value);side()"><textarea placeholder="Notes, doc numbers, who you called" onchange="setk('${id}','n',this.value)">${x.n||''}</textarea></div>`});
 if(s.calc)h+=`<h3 style="margin-top:18px">Closed comps → after-repair value</h3><div class="g">${inp('arvC','Conservative ARV $')}${inp('arvE','Expected ARV $')}${inp('arvO','Optimistic ARV $')}${inp('rep','Repair budget $')}${inp('repP','Repair contingency %')}${inp('unseen','Contingency if interior unseen %')}${inp('sqft','Subject sq ft')}</div><div id="cg"></div>
 <h3 style="margin-top:18px">Deal costs</h3><div class="g">${inp('legal','Title / legal / closing $')}${inp('poss','Possession (eviction / cash-for-keys) $')}${inp('carry','Carry per month $ (tax, ins, util)')}${inp('mo','Months to exit')}${inp('sell','Resale cost % (agent + closing)')}${inp('profP','Target profit % of ARV')}${inp('profD','Or minimum profit $')}${inp('cont','Risk contingency % ARV')}${inp('prem','Buyer premium %')}${inp('tt','Transfer tax % (verify; may be exempt)')}${inp('cap','Cost of cash %/yr')}${inp('dep','Deposit % at sale')}</div>`;
 if(s.rep)h+=report()+gateUI();if(s.id==='court')h+=gateUI();if(s.deals)h+=dealsUI();if(s.look)h+=lookUI();if(s.set)h+=setUI();if(s.lien)h+=lienUI();if(s.acc)h=h.replace('</section>','')+accUI()+'</section>';
 h+=`<p class="noprint" style="margin-top:14px">${cur>0?'<button class="btn o" onclick="go(cur-1)">Back</button> ':''}${cur<STAGES.length-1?'<button class="btn" onclick="go(cur+1)">Next stage</button>':''}</p></section>`;
 $('main').innerHTML=h;side();if(s.rep)bindRep();if(s.lien){lienOut();bindRep()}if(s.acc)accOut();if(s.calc)compsOut();if(s.set)bindSet();if(s.look)lookBind();refreshWho()}

/* ===== Purchase playbooks (general; verify against the notice of sale and with an Illinois real-estate attorney) ===== */
const SALES={judicial:{n:'Foreclosure judicial sale (Illinois)',s:['Find who actually conducts the sale. A Hubzu or Auction.com listing can be marketing only; the sale may be live, run by the plaintiff\u2019s attorney or a court-appointed officer. Get the Notice of Sale.','Pull the docket and judgment. Redemption rights expire before a judicial sale (for homes, the later of 7 months from service or 3 months from judgment), so do not budget a post-sale redemption wait. A narrow 30-day special redemption right after confirmation can apply in some cases; ask your attorney.','Confirm deposit and balance terms in the notice or listing (for example 10% or 20% down, balance within 24 hours) and prepare certified funds. Cards and Stripe will not work.','Day of sale: re-check PACER and the docket. A bankruptcy filing or stay ends the sale.','Bid no higher than the ceiling. The sale is as-is, usually with no interior inspection, and your deposit is at risk if you do not close.','Pay the balance by the deadline. For any wire, first call the title company or sale officer at a number you found yourself.','You receive a Certificate of Sale, subject to court confirmation. The court then approves the sale and you receive the judicial sale deed. Record it with the Recorder.','Possession: an occupant may need a court order of possession; budget eviction or cash-for-keys.','Insure the property at once. Get the association\u2019s statement and an attorney\u2019s read on what a foreclosure buyer owes for taxes and dues before bidding.']},
reo:{n:'Bank-owned / REO auction',s:['Register on the platform (Auction.com, Hubzu, Xome, etc.); read the bid terms and buyer-premium.','Proof of funds up front (use Plaid verification below).','Bid at or below ceiling, premium included.','Earnest money per terms; wire to the title company only after verifying instructions by phone at a number you found yourself. Read the as-is and default terms.','Order your own title search/commitment; close via title company; record the deed.']},
tax:{n:'Tax sale / scavenger',s:['A tax sale buys a lien or redemption right, not clean ownership. Do not use the ceiling above as-is.','Confirm redemption period and notice requirements with an attorney before bidding.','Tax-deed petition process is court-driven and slow; budget legal costs and time.']},
private:{n:'Private / off-market cash purchase',s:['Order title commitment before signing; keep an attorney review contingency.','Sign contract at or below ceiling with inspection and title contingencies.','Wire only to a verified title company; close, record the deed, and insure.']}};

/* ===== Report ===== */
function report(){const v=S.v,p=S.p,{open,kill}=status(),sl=SALES[p.sale];
 const rows=[['Conservative',v.arvC],['Expected',v.arvE],['Optimistic',v.arvO]].map(r=>`<tr><td>${r[0]}</td><td>${m(r[1])}</td><td>${r[1]?m(bid(r[1])):'—'}</td></tr>`).join('');
 const iss=[];STAGES.forEach(s=>(s.c||[]).forEach((c,i)=>{if(off(c))return;const x=S.k[key(s,i)]||{};if(x.s==='issue'||x.s==='kill')iss.push(`- ${c.t}: ${x.s==='kill'?'DEALBREAKER':'issue'} ${x.a?m(+x.a):''} ${x.n||''}`)}));
 const b=bid(v.arvC);
 const txt=`ACQUISITION REPORT – ${p.addr||'(no address)'}\nCounty: ${p.county}   PIN: ${p.pin||'-'}   Owner: ${p.owner||'-'}\nSale type: ${sl.n}   Sale date: ${p.date||'-'}\nCase: ${p.case||'-'}   Plaintiff/attorney: ${p.plf||'-'} ${p.plph||''}   Conducted by: ${p.venue||'-'}\nOccupancy: ${p.occ||'-'}   Interior inspection: ${p.insp||'-'}   Opening/credit bid: ${+p.cb?m(+p.cb):'-'}   Payment terms: ${p.pay||'-'}\n\nRECOMMENDATION\n${kill.length?'WALK AWAY. Dealbreakers: '+kill.join('; '):!v.arvC?'Enter comps to compute a price.':`Pay no more than ${m(b)} (all-in bid before buyer premium). Do not exceed it at the sale.${open?`\nProvisional: ${open} research checks still open.`:''}`}${gatesOpen()?'\nDO NOT BID YET: '+gatesOpen()+' pre-bid gates are open.':''}\n\nPRE-BID GATES\n${GATES.map(g=>(gOk(g[0])?'[x] ':'[ ] ')+g[1]).join('\n')}\n\nHOW MUCH\nConservative ARV ${m(v.arvC)}; repairs ${m(v.rep)} + ${repC()}% contingency (${p.acc==='full'?'interior seen':'interior NOT fully seen'}); surviving liens/exposure ${m(exposure())}; possession ${m(v.poss)}; carry ${m(v.carry*v.mo)}; resale costs ${v.sell}%; profit target ${Math.max(v.profD,v.arvC*v.profP/100)>0?m(Math.max(v.profD,v.arvC*v.profP/100)):'-'}; cost of cash ${v.cap}%/yr.\nCash to deploy (bid + premium + transfer tax + repairs + legal + possession + surviving liens): ${m(cashNeeded(b))}\nRule-of-thumb check (70% of conservative ARV minus repairs): ${m(v.arvC*.7-v.rep)}\n\nFINDINGS\n${iss.join('\n')||'No issues logged.'}\n\nHOW TO BUY (${sl.n})\n${sl.s.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\nNot legal advice. Confirm sale terms in the official notice and use an Illinois real-estate attorney and a title search before bidding.`;
 window._rep=txt;
 return`<h3>Scenarios</h3><table><tr><th></th><th>ARV</th><th>Max bid</th></tr>${rows}</table><p class="lead">Bid from the conservative row only.</p>
 <div id="rep">${txt.replace(/</g,'&lt;')}</div>
 <p class="noprint"><button class="btn" onclick="window.print()">Print / PDF</button> <button class="btn o" onclick="saleIcs()">Sale-day calendar</button> <button class="btn o" onclick="navigator.clipboard.writeText(_rep).then(()=>say('Copied.'),()=>say('Copy blocked by browser – select the text and copy manually.'))">Copy</button> <button class="btn o" id="bEm">Email me this (Resend)</button> <button class="btn o" id="bSv">Save all deals (Supabase)</button> <button class="btn o" id="bPl">Verify funds (Plaid)</button> <button class="btn o" id="bSt">Pay (Stripe)</button></p><p id="msg" class="cfg"></p>
 <p class="cfg">Signed in with your investor account. Your deals save to your private cloud space with Save all deals.</p>`}
const say=t=>{const e=$('msg');if(e)e.textContent=t};
async function api(path,body){if(!CFG.API_BASE)throw Error('Set CFG.API_BASE to your Cloudflare Worker URL');
 const t=sb?(await sb.auth.getSession()).data.session?.access_token:"";if(!t)throw Error("Your sign-in expired: reload the page and sign in again");
 const r=await fetch(CFG.API_BASE+path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+t},body:JSON.stringify(body||{})});
 const j=await r.json();if(!r.ok)throw Error(j.error||r.status);return j}
function bindRep(){const g=id=>$(id),w=(id,f)=>g(id)&&(g(id).onclick=async()=>{try{say('Working…');await f()}catch(e){say('Error: '+e.message)}});
 w('bEm',async()=>{await api('/email',{subject:'Acquisition report – '+(S.p.addr||''),text:_rep});say('Sent to your sign-in email.')});
 w('bSv',async()=>{const n=await cloudPush();say('Saved '+n+' deal(s) to your cloud space.')});
 w('bSt',async()=>{const a=prompt('Amount in USD (e.g. report fee or deposit):');if(!a)return;const j=await api('/stripe/checkout',{amount:Math.round(a*100),desc:'Deal '+(S.p.addr||''),back:location.href});location=j.url});
 w('bPl',async()=>{const t=await api('/plaid/link-token');Plaid.create({token:t.link_token,onSuccess:async pt=>{try{await api('/plaid/exchange',{public_token:pt});const b=await api('/plaid/balance');S.funds=b.available;save();draw();}catch(e){say('Error: '+e.message)}}}).open()})}

/* ===== Tax-lien mode: Illinois annual tax sale. Statutory dates are estimates from public sources; confirm with an attorney. ===== */
const CO={Cook:{max:18,sale:'Dec 15, 2026 (Treasurer site; confirm)',u:'https://www.cooktaxsale.com/'},Lake:{max:18,sale:'Nov 13, 2026 (county tax calendar)',u:'https://www.lakecountyil.gov/3522/Real-Estate-Tax-Calendar'},McHenry:{max:9,sale:'Nov 16, 2026 (Treasurer site)',u:'https://www.mchenrycountyil.gov/departments/treasurer/your-property-taxes/tax-sale'},Winnebago:{max:18,sale:'Late Oct / early Nov (date set by Treasurer)',u:'https://wincoil.gov/departments/treasurer/tax-information'},Boone:{max:18,sale:'Ask the Boone County Collector',u:''},Other:{max:18,sale:'Ask the county collector',u:''}};
const U=x=>new Date(x+'T00:00:00Z'),iso=d=>d.toISOString().slice(0,10),fd=d=>d.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'});
const am=(d,n,x=0)=>{const r=new Date(d),day=r.getUTCDate();r.setUTCDate(1);r.setUTCMonth(r.getUTCMonth()+n);r.setUTCDate(Math.min(day,new Date(Date.UTC(r.getUTCFullYear(),r.getUTCMonth()+1,0)).getUTCDate())+x);return r};
const redM=()=>{const t=S.t;return +t.redm||(t.cls==='res'?(U(t.date)>=U('2026-07-10')?36:30):12)};
function sched(){const t=S.t,D=U(t.date),rm=redM(),R=am(D,rm),E=[];
 E.push([D,'Sale: bid and pay','Registration, deposit and payment rules are set by the county collector. Collect your certificate of purchase.',0]);
 E.push([am(D,4,15),'DEADLINE: deliver sale notice (22-5) to the county clerk','Miss it and you cannot get a tax deed. The clerk mails it to the taxpayer.',1]);
 for(let k=1;k<rm/6;k++)E.push([am(D,6*k),'Penalty step '+(k+1)+' begins','Redemption amount rises by your bid rate each six-month period.',0]);
 E.push([am(R,-8),'Recommended: order title and owner/occupant search','So you know who must be served. My recommendation, not a statutory date.',0]);
 E.push([am(R,-6),'Window opens: expiration notice (22-10) and tax deed petition (22-30)','Both must fall between 6 and 3 months before redemption expires.',0]);
 E.push([am(R,-5),'Recommended target: file petition and start service','Practitioners file early so the sheriff has time to serve occupants.',0]);
 E.push([am(R,-3),'DEADLINE: last day for expiration notice and petition','Hard stop. Or extend the redemption period before it passes.',1]);
 E.push([R,'Redemption period expires','You may extend by filing with the county clerk before this date, to no later than 3 years from the sale.',1]);
 E.push([am(R,12),'Tax deed must be issued and recorded by','One year after expiry per a practitioner source. Confirm, and confirm the auction procedure for post-7/10/2026 certificates.',1]);
 return{E:E.sort((a,b)=>a[0]-b[0]),R,rm}}
function lcalc(){const t=S.t,A=+t.amt||0,r=(+t.rate||0)/100,rm=redM(),per=Math.ceil(rm/6),mx=CO[t.county].max;
 const minR=Math.min(mx,(+t.tgt/100)*((+t.hold||12)/12)/Math.ceil((+t.hold||12)/6)*100);
 const owed=A*(1+r*per)+(+t.subs||0),pen=A*r*per,deedProfit=pen-(+t.deedc||0)-(+t.fee||0);
 return{A,r,rm,per,mx,minR,owed,pen,deedProfit,cover:owed?(+t.val||0)/owed:0}}
function lienUI(){const t=S.t,i=(k,l,o={})=>inp(k,l,{o:t,w:'t',...o});
 return`<div class="cfg" style="margin-bottom:12px">Key risk: Illinois changed tax-sale law on July 10, 2026 (Public Act 104-0553): longer redemption, surplus equity returned to the former owner, and counties may elect to buy all delinquent taxes themselves. Check that your county is offering liens to private buyers this year.</div>
 <div class="g"><label>County<select onchange="setv('county',this.value,'t')">${Object.keys(CO).map(c=>`<option${t.county==c?' selected':''}>${c}</option>`).join('')}</select></label>
 ${i('date','Sale date',{t:'date'})}<label>Property class<select onchange="setv('cls',this.value,'t')"><option value="res"${t.cls=='res'?' selected':''}>Residential, 1-6 units</option><option value="com"${t.cls!='res'?' selected':''}>Commercial / industrial / vacant / 7+ units</option></select></label>
 ${i('amt','Taxes purchased $ (lien amount)')}${i('rate','Your bid rate % per 6 months')}${i('subs','Later taxes you expect to pay $')}${i('deedc','Deed costs if it goes to deed $')}${i('fee','Surplus-equity fees $ (verify)')}${i('val','Estimated property value $')}${i('tgt','Target return % per year')}${i('hold','Typical months until redemption')}${i('redm','Redemption months override (blank = auto)')}</div>
 <div id="lo"></div><p class="noprint"><button class="btn" onclick="window.print()">Print / PDF</button> <button class="btn o" onclick="ics()">Download calendar (.ics)</button> <button class="btn o" onclick="navigator.clipboard.writeText(_rep).then(()=>say('Copied.'),()=>say('Copy blocked'))">Copy</button> <button class="btn o" id="bEm">Email me this (Resend)</button></p><p id="msg" class="cfg"></p>`}
function lienOut(){const t=S.t,c=lcalc(),{E,R,rm}=sched(),co=CO[t.county],rows=[];
 for(let k=1;k<=c.per;k++)rows.push(`<tr><td>Redeemed within period ${k}</td><td>by ${fd(am(U(t.date),6*k))}</td><td>${m(c.A*c.r*k)}</td><td>${m(c.A+c.A*c.r*k)}</td></tr>`);
 const warn=[];if(!c.A)warn.push('Enter the lien amount.');if(c.r*100>c.mx)warn.push(`Bid rate is above the ${c.mx}% maximum I found for ${t.county}.`);if(c.r*100<c.minR-.001)warn.push(`At ${t.rate}% you earn less than your ${t.tgt}% target if redeemed in ${t.hold} months.`);if(t.val&&c.cover<3)warn.push('Value is less than 3x what you are owed: thin cover. Check for environmental and senior-lien risk, especially on commercial.');if(t.cls!='res')warn.push('Commercial/vacant redemption defaults to 12 months, which is the shorter period in the pre-2026 statute text I found. Confirm 35 ILCS 200/21-350(a) as amended.');
 const sc=E.map(e=>`${iso(e[0])}  ${e[4]?'':''}${e[3]?'[HARD] ':''}${e[1]}`).join('\n');
 window._rep=`TAX LIEN PLAN - ${S.p.addr||S.p.pin||'(parcel)'}\nCounty: ${t.county}  Sale: ${t.date}  Redemption: ${rm} months, expires ${iso(R)}\nLien ${m(c.A)}  Bid rate ${t.rate}% per 6 months\n\nRETURN IF REDEEMED\n${Array.from({length:c.per},(_,k)=>`Period ${k+1} (by ${iso(am(U(t.date),6*(k+1)))}): penalty ${m(c.A*c.r*(k+1))}`).join('\n')}\n\nBID RATE TO ACCEPT\nNot below ${c.minR.toFixed(1)}% for a ${t.tgt}%/yr target (county max ${c.mx}%).\n\nIF NEVER REDEEMED\nTotal owed to you ${m(c.owed)}; estimated profit after deed costs and fees ${m(c.deedProfit)}. Under the July 2026 law, value above what you are owed goes to the former owner (confirm with counsel).\n\nDATES\n${sc}\n\n${warn.length?'FLAGS\n'+warn.join('\n')+'\n\n':''}Statutory dates are estimates from public sources. Not legal advice; use an Illinois tax-deed attorney.`;
 $('lo').innerHTML=`<p class="lead" style="margin-top:14px">${t.county} sale: ${co.sale}. ${co.u?`<a href="${co.u}" target="_blank" rel="noopener">County sale page</a>`:''}</p>
 <h3>Bid rate to accept</h3><p>Do not accept a rate below <b>${c.minR.toFixed(1)}%</b> per six months (${t.tgt}%/yr target, redeemed in about ${t.hold} months). County maximum: ${c.mx}%.</p>
 ${warn.map(w=>`<p class="red">${w}</p>`).join('')}
 <h3>Returns if the owner redeems</h3><table><tr><th>When</th><th></th><th>Your penalty</th><th>Paid back</th></tr>${rows.join('')}</table><p class="lead">Early-redemption tiers in the first period may pay less than a full period; verify in 21-355. Later taxes you pay are not included.</p>
 <h3>If never redeemed</h3><p>You are owed ${m(c.owed)}. After deed costs and fees your estimated profit is <b>${m(c.deedProfit)}</b>. You do not keep the property's value above that under the 2026 law.</p>
 <h3>Dated steps</h3><table>${E.map(e=>`<tr><td>${fd(e[0])}</td><td style="text-align:left;${e[3]?'color:var(--bad);font-weight:600':''}">${e[1]}<div class="lead" style="margin:0;font-size:12px;font-weight:400">${e[2]}</div></td></tr>`).join('')}</table>`}
window.ics=()=>{const st=new Date().toISOString().replace(/[-:]/g,'').slice(0,15)+'Z',z=x=>iso(x).replace(/-/g,''),c=x=>String(x).replace(/[,;\n]/g,' ');
 let o='BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//CashDesk//EN\r\n';sched().E.forEach((e,i)=>{o+=`BEGIN:VEVENT\r\nUID:${z(e[0])}-${i}@cashdesk\r\nDTSTAMP:${st}\r\nDTSTART;VALUE=DATE:${z(e[0])}\r\nDTEND;VALUE=DATE:${z(am(e[0],0,1))}\r\nSUMMARY:${c((e[3]?'DEADLINE ':'')+e[1]+' - '+(S.p.addr||S.p.pin||'tax lien'))}\r\nDESCRIPTION:${c(e[2])}\r\n`+(e[3]?'BEGIN:VALARM\r\nTRIGGER:-P14D\r\nACTION:DISPLAY\r\nDESCRIPTION:Deadline in 14 days\r\nEND:VALARM\r\n':'')+'END:VEVENT\r\n'});
 o+='END:VCALENDAR';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([o],{type:'text/calendar'}));a.download='tax-lien-dates.ics';a.click()};

/* ===== Access & control ===== */
const SIG=[['cut','Lawn cut / snow cleared','Someone maintains it: owner, relative, or a preservation vendor. Look for vendor stickers.'],['vend','Vendor sticker / winterization tag','Servicer or bank vendor. Ask the plaintiff\u2019s attorney or servicer who controls it.'],['lock','Lockbox / key box','Bank-owned or listed. Find the listing agent or auction platform.'],['mail','Mail piling up / flyers','Not occupied or not collected, so letters may not reach them. Try several addresses.'],['car','Cars or lights change','Occupied. Find out whether owner or tenant.'],['meter','Heat / AC / meter running','Someone pays utilities: occupied or maintained.'],['post','Notices posted (court, city)','Read them. They name the plaintiff, case number or responsible party.'],['board','Boarded / secured by city','Code enforcement has a file with contacts and liens.'],['trash','Trash cans out on pickup day','Likely occupied.'],['sq','Unexplained occupants','Do not approach or enter. Possession problem for counsel and police.']];
const LAD=[['mail','Tax-bill mailing address','https://www.cookcountytreasurer.com/','pin','Bills go where the owner or lender escrow said. An address different from the property is your first lead. Lake: use the Lake property search.'],['deed','Owner of record (latest deed)','https://crs.cookcountyclerkil.gov/','pin','Who holds title, and whether it is a person, estate, trust or LLC.'],['mtg','Mortgage and assignments','https://crs.cookcountyclerkil.gov/','pin','Names the lender. Ask the lender who services the loan.'],['dock','Foreclosure docket','https://casesearch.cookcountyclerkofcourt.org/','name','Plaintiff\u2019s attorney, any court-appointed receiver, service returns naming occupants, orders of possession.'],['ent','LLC / entity','https://apps.ilsos.gov/businessentitysearch/','name','Registered agent and managers can say yes for an entity.'],['prob','Probate (if owner died)','https://casesearch.cookcountyclerkofcourt.org/','name','Letters of office name the representative who can act.'],['city','City / code enforcement file','https://data.cityofchicago.org/','addr','Violations name a responsible party and often a contact.'],['hoa','HOA / condo association','https://apps.ilsos.gov/businessentitysearch/','name','Management companies know who lives there and who pays assessments.'],['nbr','Neighbors','','','Ask honestly who looks after it. Say who you are.'],['skip','People search (public records)','https://www.truepeoplesearch.com/','name','Use for finding the owner, not for harassing anyone. Mind calling and texting rules.']];
const SIT={own:['Owner lives there','The owner or an adult co-owner.','Letter, then a daytime visit. Ask to see the property; they can say no and that ends it.','If the home is in foreclosure or tax-delinquent, any purchase from the owner falls under the Illinois Mortgage Rescue Fraud Act (see below).'],ten:['Tenant lives there','The tenant has the right to possession; the landlord cannot simply walk you in.','Reach the landlord and ask them to arrange a showing with the notice the lease and local law require (Chicago has its own ordinance). Never pressure a tenant.','Do not enter on the landlord\u2019s say-so alone.'],vac:['Vacant, owner found','The owner, in writing.','Signed access agreement: date and time window, who attends, no alterations, your liability insurance, hold-harmless. Bring a second person and an inspector.','No opening lockboxes, no open doors or windows, no entering because it looks abandoned.'],reo:['Bank-owned (REO)','The bank\u2019s listing agent or the auction platform.','Find the listing agent; ask in writing about inspection windows and terms.','Never remove lockboxes or notices.'],fcl:['Foreclosure pending','The owner or occupant, or the plaintiff/servicer or a court-appointed receiver if they hold possession.','Check the docket for a receiver. Ask plaintiff\u2019s attorney whether pre-sale access is offered. Judicial sales are usually as-is with no inspection, so price in the unseen interior (the tool does).','Do not assume the plaintiff or auction house can let you in.'],tax:['You hold a tax certificate','Nobody owes you access. You have a lien, not possession, until a deed and possession order.','Your notice duties force contact: you must make a diligent inquiry and serve owners, occupants and interested parties. Record exterior observations and occupancy, and give them to your tax-deed attorney.','Asking the owner for a look, or buying their interest, falls under the Mortgage Rescue Fraud Act.'],est:['Owner died','The court-appointed representative once appointed; heirs alone usually cannot.','Check the probate docket for letters of office. Write to the representative or their attorney.','Do not deal with one heir as if they speak for the estate.'],ent:['LLC or trust owns it','The manager or trustee with authority.','Registered agent and manager from ILSOS; trust documents from the Recorder. Write to both.','Get proof of authority before relying on anyone\u2019s yes.'],sq:['Someone there without apparent right','Not the person inside. Their permission gives you nothing.','Stay out. Tell the owner or police as appropriate; possession is a court process for the owner or their attorney.','Never confront, change locks or remove belongings.']};
const CAD=['Touch 1: first-class and certified letter to every address found','Touch 2 (about day 3-5): daytime visit, leave a door hanger','Touch 3 (about day 7): phone call if you have a number (check calling and texting rules)','Touch 4 (about day 14): second letter, different wording','Touch 5 (about day 21): servicer, plaintiff\u2019s attorney, estate representative, registered agent or association manager','Beyond that: stop or escalate through counsel; keep your log'];
function accUI(){const a=S.a,p=S.p,td=new Date().toLocaleDateString('en-CA');
 return`<h3 style="margin-top:6px">Interior access</h3><div class="g"><label>What have you seen inside?<select onchange="setv('acc',this.value,'p')">${[['','Not seen'],['ext','Exterior only'],['full','Full interior walkthrough']].map(o=>`<option value="${o[0]}"${(p.acc||'')==o[0]?' selected':''}>${o[1]}</option>`).join('')}</select></label>${inp('unseen','Contingency if interior unseen %')}</div><p class="lead">Unless you have walked the interior, repairs get the higher contingency, which lowers your ceiling bid. That is the price of not getting in.</p>
 <h3>1. What your visits show</h3><div class="g"><label>Visit date<input type="date" id="vd" value="${td}"></label><label style="grid-column:span 2">Notes<input id="vn" placeholder="Who you saw, vendor names, notice text"></label></div><p>${SIG.map(x=>`<label style="display:inline-block;margin-right:14px"><input type="checkbox" class="sg" value="${x[0]}" style="width:auto;margin:0 4px 0 0">${x[1]}</label>`).join('')}</p><p><button class="btn" onclick="addVisit()">Log visit</button></p><div id="ao1"></div>
 <h3>2. Who controls it</h3><p class="lead">Each link copies the PIN, address or owner name first. Type what you find.</p>${LAD.map(x=>`<div class="chk" style="grid-template-columns:1fr 1fr"><div>${x[2]?`<a href="#" onclick="open2('${x[2]}','${x[3]}');return false">${x[1]}</a>`:`<b>${x[1]}</b>`}<div class="w">${x[4]}</div></div><input placeholder="What I found" value="${(a.who[x[0]]||'').replace(/"/g,'&quot;')}" onchange="setw('${x[0]}',this.value)"></div>`).join('')}
 <h3>3. Contact log</h3><div class="g"><label>Date<input type="date" id="cd" value="${td}"></label><label>Channel<select id="cc"><option>Letter</option><option>Certified letter</option><option>Door hanger</option><option>In person</option><option>Phone</option><option>Text</option><option>Email</option><option>Via attorney / servicer</option></select></label><label>Who<input id="cw" placeholder="Name or role"></label><label>Outcome<select id="co"><option>No response</option><option>Returned undeliverable</option><option>Spoke, interested</option><option>Spoke, declined</option><option>Asked me to stop</option><option>Access agreed</option></select></label></div><p><button class="btn" onclick="addContact()">Log attempt</button></p><div id="ao2"></div>
 <h3>4. Your situation</h3><div class="g"><label>Situation<select onchange="seta('sit',this.value)">${Object.entries(SIT).map(([k,v])=>`<option value="${k}"${a.sit==k?' selected':''}>${v[0]}</option>`).join('')}</select></label><label>Letter<select onchange="seta('lt',this.value)"><option value="owner"${a.lt=='owner'?' selected':''}>To the owner</option><option value="occ"${a.lt=='occ'?' selected':''}>To the resident</option><option value="serv"${a.lt=='serv'?' selected':''}>To servicer / plaintiff\u2019s attorney</option></select></label><label>Your name<input value="${a.me}" onchange="setw2('me',this.value)"></label><label>Phone / email<input value="${a.ph}" onchange="setw2('ph',this.value)"></label></div><div id="ao3"></div>`}
window.setw=(k,v)=>{S.a.who[k]=v;save()};window.setw2=(k,v)=>{S.a[k]=v;save();accOut()};window.seta=(k,v)=>{S.a[k]=v;save();accOut()};
window.addVisit=()=>{S.a.visits.push({d:$('vd').value,n:$('vn').value,s:[...document.querySelectorAll('.sg:checked')].map(x=>x.value)});document.querySelectorAll('.sg').forEach(x=>x.checked=false);$('vn').value='';save();accOut()};
window.addContact=()=>{S.a.contacts.push({d:$('cd').value,c:$('cc').value,w:$('cw').value,o:$('co').value});$('cw').value='';save();accOut()};
window.delA=(k,i)=>{S.a[k].splice(i,1);save();accOut()};
const esc=x=>String(x||'').replace(/&/g,'&amp;').replace(/</g,'&lt;');
function letterText(){const p=S.p,a=S.a,addr=p.addr||'[address]',me=`${a.me||'[your name]'}\n${a.ph||'[phone or email]'}`;
 return{owner:`Re: ${addr}\n\nDear ${p.owner||'Property Owner'},\n\nMy name is ${a.me||'[your name]'}. I buy property in this area for cash, and I am interested in yours. I am not a lender, a court, or a government agency, and you are under no obligation to reply.\n\nIf you would like to talk about a sale, or let me see the property at a time that suits you, please contact me below. If you would rather not hear from me, tell me and I will stop.\n\nBefore making any decision about your property, you may want to speak with an attorney of your choice.\n\n${me}`,occ:`To the resident at ${addr}:\n\nMy name is ${a.me||'[your name]'}. I am trying to reach the owner or whoever manages this property. I am not a lender, a court, or a government agency. If you can tell me how to reach them, or pass on my details, I would be grateful. You do not need to let me in or tell me anything about yourself.\n\n${me}`,serv:`Re: ${addr}${p.pin?' (PIN '+p.pin+')':''}\n\nTo the servicer / plaintiff\u2019s counsel:\n\nI am a prospective cash purchaser. Please tell me (1) who currently controls access to the property, (2) whether interior inspection is offered before the sale and how to request it, and (3) the sale date and terms. I understand a sale may be as-is and without inspection.\n\n${me}`}[a.lt]}
function accOut(){const a=S.a,n=a.visits.length,cnt={};a.visits.forEach(v=>v.s.forEach(k=>cnt[k]=(cnt[k]||0)+1));
 $('ao1').innerHTML=n?`${SIG.filter(x=>cnt[x[0]]).map(x=>`<p><b>${x[1]}: seen in ${cnt[x[0]]} of ${n} visits.</b> ${x[2]}</p>`).join('')||'<p class="lead">No signs ticked yet.</p>'}<table>${a.visits.map((v,i)=>`<tr><td>${v.d}</td><td style="text-align:left">${v.s.map(k=>SIG.find(x=>x[0]==k)[1]).join(', ')||'-'} ${esc(v.n)}</td><td><a href="#" onclick="delA('visits',${i});return false">remove</a></td></tr>`).join('')}</table>`:'<p class="lead">Log each visit. Patterns across visits point to who keeps it up.</p>';
 const c=a.contacts.length;$('ao2').innerHTML=`<p><b>Suggested next:</b> ${CAD[Math.min(c,CAD.length-1)]}</p>`+(c?`<table>${a.contacts.map((x,i)=>`<tr><td>${x.d}</td><td style="text-align:left">${x.c} - ${esc(x.w)} - ${x.o}</td><td><a href="#" onclick="delA('contacts',${i});return false">remove</a></td></tr>`).join('')}</table>`:'');
 const s=SIT[a.sit];$('ao3').innerHTML=`<p><b>Who can say yes:</b> ${s[1]}</p><p><b>How to ask:</b> ${s[2]}</p><p class="red"><b>Watch out:</b> ${s[3]}</p>
 <div class="cfg" style="margin:10px 0"><b>Illinois Mortgage Rescue Fraud Act.</b> A home in foreclosure, behind on taxes, or whose owner is over 30 days behind on the mortgage is a "distressed property". Buying it from the owner needs a written contract with required notices, gives the owner at least 5 business days to cancel (or until the redemption right ends, if sooner), and must be recorded within 10 days. Intentional violations can be a Class 2 felony. Have an Illinois attorney draft the contract. It most clearly covers homes; ask whether it reaches your commercial deals.</div>
 <div class="cfg" style="margin:10px 0"><b>Never:</b> enter without permission from someone with the right to give it, including through unlocked doors or windows; open lockboxes or remove notices; pose as an inspector, utility or official; change locks or remove belongings; record calls without everyone\u2019s consent (Illinois requires it); pressure a distressed owner.</div>
 <label>Letter draft</label><div id="rep">${esc(letterText())}</div><p class="noprint"><button class="btn o" onclick="navigator.clipboard.writeText(document.getElementById('rep').innerText).then(()=>0,()=>0)">Copy letter</button></p>`}

/* ===== Deals, comps, settings, cloud ===== */
const dl=d=>d.p.addr||d.p.pin||'(untitled deal)';
function wd(d,f){const o=S;S=d;try{ensure();return f()}finally{S=o}}
function dealsUI(){const rows=Object.values(DB.deals).sort((a,b)=>(b.u||0)-(a.u||0)).map(d=>{const r=wd(d,()=>({b:bid(S.v.arvC),g:gatesOpen(),o:status().open,k:status().kill.length}));return`<tr><td style="text-align:left"><a href="#" onclick="switchDeal('${d.id}');return false"><b>${esc(dl(d))}</b></a><div class="lead" style="margin:0;font-size:12px">${d.p.county} County · ${d.p.date||'no sale date'} ${d.p.id===DB.cur?'':''}</div></td><td>${d.v.arvC?m(r.b):'-'}</td><td>${r.k?'<span class="red">walk</span>':r.g?r.g+' gates open':r.o?r.o+' checks open':'cleared'}</td><td><a href="#" onclick="delDeal('${d.id}');return false">delete</a></td></tr>`}).join('');
 return`<table><tr><th>Property</th><th>Ceiling bid</th><th>Status</th><th></th></tr>${rows}</table><p class="noprint"><button class="btn" onclick="newDeal()">New deal</button> <button class="btn o" onclick="exportDB()">Export all (JSON)</button> <label class="btn o" style="display:inline-block;cursor:pointer;margin:0">Import<input type="file" accept=".json" style="display:none" onchange="importDB(this.files[0])"></label> <button class="btn o" onclick="cloud('push')">Save all to Supabase</button> <button class="btn o" onclick="cloud('pull')">Load from Supabase</button></p><p id="msg" class="cfg">Cloud copies replace local copies only when they are newer.</p>`}
window.switchDeal=id=>{DB.cur=id;S=DB.deals[id];ensure();save();go(1)};
window.newDeal=()=>{const d=NEWDEAL();DB.deals[d.id]=d;switchDeal(d.id)};
window.delDeal=id=>{if(!confirm('Delete this deal from this device? Cloud copies are not deleted.'))return;delete DB.deals[id];if(!Object.keys(DB.deals).length){const d=NEWDEAL();DB.deals[d.id]=d}if(!DB.deals[DB.cur])DB.cur=Object.keys(DB.deals)[0];S=DB.deals[DB.cur];ensure();save();draw()};
window.exportDB=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(DB,null,1)],{type:'application/json'}));a.download='cash-desk-deals.json';a.click()};
window.importDB=f=>{if(!f)return;f.text().then(t=>{try{const x=JSON.parse(t);Object.values(x.deals||{}).forEach(d=>{if(d&&d.id&&d.p&&d.v)DB.deals[d.id]=d});S=DB.deals[DB.cur];ensure();save();draw()}catch(e){say('Import failed: not a deals file.')}})};
async function cloudPush(){if(!sb)throw Error('Sign in at /investor/ first');const{data:{user}}=await sb.auth.getUser();if(!user)throw Error('Sign in first (Settings)');const rows=Object.values(DB.deals).map(d=>({user_id:user.id,id:d.id,pin:d.p.pin||d.p.addr||'',data:d,updated:new Date().toISOString()}));const{error}=await sb.from('investor_deals').upsert(rows,{onConflict:'user_id,id'});if(error)throw error;return rows.length}
async function cloudPull(){if(!sb)throw Error('Sign in at /investor/ first');const{data:{user}}=await sb.auth.getUser();if(!user)throw Error('Sign in first (Settings)');const{data,error}=await sb.from('investor_deals').select('id,data');if(error)throw error;let n=0;data.forEach(r=>{const l=DB.deals[r.id];if(!l||(r.data.u||0)>(l.u||0)){DB.deals[r.id]=r.data;n++}});S=DB.deals[DB.cur]||Object.values(DB.deals)[0];DB.cur=S.id;ensure();save();return n}
window.cloud=async w=>{try{say('Working…');const n=w==='push'?await cloudPush():await cloudPull();if(w==='pull')draw();say((w==='push'?'Saved ':'Loaded ')+n+' deal(s).')}catch(e){say('Error: '+(e.message||e))}};
async function refreshWho(){const e=$('who');if(!e)return;if(!sb){e.textContent='Local-only mode';return}const{data:{session}}=await sb.auth.getSession();e.innerHTML=session?`${esc(session.user.email)} · <a href="#" onclick="window.deskSignOut();return false">sign out</a>`:'Not signed in';}
if(sb)sb.auth.onAuthStateChange(()=>refreshWho());
function compsCalc(){const sq=+S.v.sqft,now=Date.now(),rows=S.c.map(c=>{const adj=(+c.p||0)+(+c.j||0),est=(sq&&+c.s)?adj/ +c.s*sq:adj,age=Math.round((now-new Date(c.d))/864e5),f=[];if(age>180)f.push('older than 6 months');if(sq&&+c.s&&Math.abs(c.s-sq)/sq>.2)f.push('size differs over 20%');return{...c,est,age,f}}),e=rows.map(r=>r.est).sort((a,b)=>a-b),q=x=>{if(!e.length)return 0;const i=(e.length-1)*x,lo=Math.floor(i);return e[lo]+(e[Math.min(lo+1,e.length-1)]-e[lo])*(i-lo)};return{rows,c:q(.25),e:q(.5),o:q(.75)}}
function compsOut(){const r=compsCalc();$('cg').innerHTML=`<h3 style="margin-top:18px">Comparable sales (closed only)</h3><div class="g"><label>Address<input id="c_a"></label><label>Sold date<input type="date" id="c_d"></label><label>Sold price $<input type="number" id="c_p"></label><label>Sq ft<input type="number" id="c_s"></label><label>Adjustment $ (+/-)<input type="number" id="c_j"></label></div><p><button class="btn o" onclick="addComp()">Add comp</button> ${r.rows.length>=3?`<button class="btn" onclick="useArv()">Use as ARV: ${m(r.c)} / ${m(r.e)} / ${m(r.o)}</button>`:'<span class="lead">Add at least 3 comps to price from them.</span>'}</p>${r.rows.length?`<table><tr><th>Comp</th><th>Adjusted</th><th>Value at subject size</th><th></th></tr>${r.rows.map((x,i)=>`<tr><td>${esc(x.a)} · ${x.d||'no date'}${x.f.length?`<div class="red" style="font-size:12px">${x.f.join(', ')}</div>`:''}</td><td>${m((+x.p||0)+(+x.j||0))}</td><td>${m(x.est)}</td><td><a href="#" onclick="delComp(${i});return false">remove</a></td></tr>`).join('')}</table><p class="lead">Conservative is the 25th percentile, expected the median, optimistic the 75th.</p>`:''}`}
window.addComp=()=>{const g=i=>$(i).value;if(!g('c_p'))return;S.c.push({a:g('c_a'),d:g('c_d'),p:g('c_p'),s:g('c_s'),j:g('c_j')});save();compsOut()};
window.delComp=i=>{S.c.splice(i,1);save();compsOut()};
window.useArv=()=>{const r=compsCalc();S.v.arvC=Math.round(r.c);S.v.arvE=Math.round(r.e);S.v.arvO=Math.round(r.o);save();draw()};
function setUI(){return`<div class="g"><label>Worker URL (email, Stripe and Plaid; optional)<input id="cs3" value="${esc(CFG.API_BASE)}" placeholder="https://desk-api.you.workers.dev"></label></div><p class="noprint"><button class="btn" id="sSave">Save</button> <button class="btn o" id="sTest">Test Worker</button> <button class="btn o" id="sOut">Sign out</button></p><p id="msg" class="cfg">Never paste Stripe, Resend or Plaid secrets here. They belong in the Worker.</p>`}
function bindSet(){const g=id=>$(id);g("sSave").onclick=()=>{localStorage.setItem("deskcfg",JSON.stringify({API_BASE:g("cs3").value.trim().replace(/\/+$/,"")}));location.reload()};
 g("sTest").onclick=async()=>{try{say("Testing…");const r=await fetch(g("cs3").value.trim().replace(/\/+$/,"")+"/health");say("Worker says: "+JSON.stringify(await r.json()))}catch(e){say("Cannot reach the Worker: "+e.message)}};
 g("sOut").onclick=()=>window.deskSignOut()}
window.saleIcs=()=>{const D=S.p.date;if(!D){say('Enter the sale date on Identify first.');return}const z=x=>x.replace(/-/g,''),n=iso(am(U(D),0,1)),n2=iso(am(U(D),0,2)),c=x=>String(x).replace(/[,;\n]/g,' '),st=new Date().toISOString().replace(/[-:]/g,'').slice(0,15)+'Z',ev=[[D,n,'SALE DAY: bid no higher than '+m(bid(S.v.arvC)),'Re-check PACER and the docket first. Certified funds ready.'],[D,n,'Morning of sale: PACER and docket check','Bankruptcy or stay means no bid.'],[n,n2,'Balance due per Notice of Sale (confirm deadline)','Often within 24 hours. Verify wire instructions by phone.']];
 let o='BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//CashDesk//EN\r\n';ev.forEach((e,i)=>{o+=`BEGIN:VEVENT\r\nUID:${z(e[0])}-s${i}@cashdesk\r\nDTSTAMP:${st}\r\nDTSTART;VALUE=DATE:${z(e[0])}\r\nDTEND;VALUE=DATE:${z(e[1])}\r\nSUMMARY:${c(e[2]+' - '+dl(S))}\r\nDESCRIPTION:${c(e[3])}\r\nBEGIN:VALARM\r\nTRIGGER:-P1D\r\nACTION:DISPLAY\r\nDESCRIPTION:Sale reminder\r\nEND:VALARM\r\nEND:VEVENT\r\n`});o+='END:VCALENDAR';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([o],{type:'text/calendar'}));a.download='sale-day.ics';a.click()};
{const n0=nav;nav=function(){n0();refreshWho()}}

draw();
